// src/polish.js — the Step 9 realism kit (issue #19). Every surface here is a
// procedural canvas drawn once at import (never in the render path), seeded
// through hash1 so every boot paints the identical pixels — the same rule as
// src/textures.js, whose file stays byte-stable so the Step 3 baselines still
// hold. Nothing is downloaded, scanned or generated by an image model.
//
// What this adds over Step 8's furniture textures:
//   * real normal maps (a Sobel pass over the height the draw produced), so
//     grain, grout and weave catch the window light instead of being flat colour
//   * roughness maps, so a worn plank edge is matte and a porcelain rim is not
//   * `worldUV` — triplanar-lite UVs baked from world position, which is what
//     makes a MERGED furniture mesh carry a texture at all (merged geometry has
//     no per-part UVs, so Step 8's grain only reached the unmerged meshes)
//   * contact shadows: one InstancedMesh of soft radial pools, which is what
//     actually makes props look like they weigh something
//   * leaf geometry with a midrib and a tip, and two plant types to populate it

import * as THREE from 'three';
import { TOKENS } from './tokens.js';
import { hash1, clamp } from './util.js';

// ---------------------------------------------------------------------------
// 1. Canvas plumbing
// ---------------------------------------------------------------------------
function paintCanvas(size, draw) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  draw(ctx, size);
  return c;
}

function makeTexture(canvasEl, { srgb = true, repeat = [1, 1] } = {}) {
  const t = new THREE.CanvasTexture(canvasEl);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.anisotropy = 8; // walls get viewed at brutal grazing angles by the diorama cam
  return t;
}

/** A colour map from a draw call. */
function colourMap(size, draw, opts = {}) {
  return makeTexture(paintCanvas(size, draw), opts);
}

/** A data map (roughness / metalness): linear, no colour space. */
function dataMap(size, draw, opts = {}) {
  return makeTexture(paintCanvas(size, draw), { ...opts, srgb: false });
}

/**
 * Turn a height drawing (grayscale luminance) into a tangent-space normal map
 * with a Sobel pass. `strength` is how deep the relief reads, in texel slope.
 * This is the cheap half of "believable materials": no geometry, one 2D pass.
 */
function normalMapFrom(size, drawHeight, { strength = 2.2, repeat = [1, 1] } = {}) {
  const src = paintCanvas(size, drawHeight);
  const sctx = src.getContext('2d');
  const h = sctx.getImageData(0, 0, size, size);
  const out = paintCanvas(size, () => {});
  const octx = out.getContext('2d');
  const img = octx.createImageData(size, size);
  const at = (x, y) => {
    const xi = (x + size) % size;
    const yi = (y + size) % size;
    const i = (yi * size + xi) * 4;
    // luminance of the height canvas, already grey in practice
    return (0.2126 * h.data[i] + 0.7152 * h.data[i + 1] + 0.0722 * h.data[i + 2]) / 255;
  };
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx =
        at(x - 1, y - 1) + 2 * at(x - 1, y) + at(x - 1, y + 1) -
        (at(x + 1, y - 1) + 2 * at(x + 1, y) + at(x + 1, y + 1));
      const dy =
        at(x - 1, y - 1) + 2 * at(x, y - 1) + at(x + 1, y - 1) -
        (at(x - 1, y + 1) + 2 * at(x, y + 1) + at(x + 1, y + 1));
      let nx = dx * strength;
      let ny = dy * strength;
      const nz = 1;
      const len = Math.hypot(nx, ny, nz) || 1;
      nx /= len; ny /= len;
      const i = (y * size + x) * 4;
      img.data[i] = Math.round((nx * 0.5 + 0.5) * 255);
      img.data[i + 1] = Math.round((ny * 0.5 + 0.5) * 255);
      img.data[i + 2] = Math.round((nz / len) * 0.5 * 255);
      img.data[i + 3] = 255;
    }
  }
  octx.putImageData(img, 0, 0);
  return makeTexture(out, { srgb: false, repeat });
}

// ---------------------------------------------------------------------------
// 2. worldUV — triplanar-lite, so merged props carry their texture
// ---------------------------------------------------------------------------
/**
 * Bake planar UVs from world position onto a geometry whose transform is
 * already applied: every vertex is projected along its dominant normal axis
 * and divided by `tile` (metres per texture tile). Because the projection uses
 * world coordinates, a bookshelf plank and a coffee-table leg end up at the
 * same texel density, which is the whole reason merged grain looks like wood
 * rather than wallpaper.
 */
function worldUV(geo, tile = 0.6) {
  const pos = geo.attributes.position;
  const nor = geo.attributes.normal;
  const n = pos.count;
  const uv = new Float32Array(n * 2);
  for (let i = 0; i < n; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const z = pos.getZ(i);
    let ax = 0;
    let ay = 0;
    let az = 0;
    if (nor) {
      ax = Math.abs(nor.getX(i));
      ay = Math.abs(nor.getY(i));
      az = Math.abs(nor.getZ(i));
    }
    let u;
    let v;
    const sx = nor ? nor.getX(i) : 0;
    const sy = nor ? nor.getY(i) : 0;
    const sz = nor ? nor.getZ(i) : 0;
    if (ay >= ax && ay >= az) {
      // facing ±Y: look down the Y axis. The SIGN decides the handedness:
      // (u,v) must run right-handed about the face normal (du × dv = N), or
      // the tangent-space normal map mirrors on the face's underside and the
      // relief inverts — faces read black instead of bumpy.
      u = x;
      v = sy >= 0 ? -z : z;
    } else if (ax >= az) {
      u = sx >= 0 ? -z : z;
      v = y;
    } else {
      u = sz >= 0 ? x : -x;
      v = y;
    }
    uv[i * 2] = u / tile;
    uv[i * 2 + 1] = v / tile;
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  return geo;
}

// ---------------------------------------------------------------------------
// 3. The surfaces (colour + normal + roughness, one object each)
// ---------------------------------------------------------------------------

/** Walnut: plank seams, wandering grain, cathedral figure, open-pore specks,
 *  and edges a shade worn. Tile = 0.6 m. */
const WOOD_H = (ctx, s) => {
  ctx.fillStyle = '#808080';
  ctx.fillRect(0, 0, s, s);
  const plank = s / 3;
  for (let p = 0; p < 3; p++) {
    // No grain grooves in the height field. Tested with them: the game's
    // low raking sun turns every parallel micro-groove into a black bar
    // (perturbed normals face away from a near-tangent light — this is
    // plain Lambert, not shadow acne, so no bias trick fixes it). Grain
    // lives in the colour map, where it reads the same way real varnished
    // wood does: as pigment, not relief. Only the plank seam stays a
    // groove, and it is shallow.
    // seam between planks: a soft groove, not a trench
    ctx.fillStyle = 'rgba(88,88,88,0.65)';
    ctx.fillRect(0, (p + 1) * plank - 2, s, 3);
    ctx.fillStyle = 'rgba(250,250,250,0.16)';
    ctx.fillRect(0, (p + 1) * plank + 1.4, s, 1);
  }
  for (let i = 0; i < 220; i++) {
    // open pores
    ctx.fillStyle = `rgba(18,18,18,${0.25 + hash1(i * 1.7) * 0.4})`;
    ctx.fillRect(hash1(i * 3.1) * s, hash1(i * 5.3) * s, 1 + hash1(i) * 2, 1);
  }
};
// NOTE on colour bases: every map here is WHITE-based with translucent
// dark/light detail, because a StandardMaterial multiplies `map` by `color`.
// The material supplies the token colour (docs/ART_STYLE.md owns those
// numbers); a pre-tinted map would square the colour — walnut 0x6b4a30
// squared renders near-black, which is how a "richer" pass ends up dark.
const woodMap = colourMap(256, (ctx, s) => {
  ctx.fillStyle = '#fdf6ec'; // warm white; the walnut colour comes from the material
  ctx.fillRect(0, 0, s, s);
  const plank = s / 3;
  for (let p = 0; p < 3; p++) {
    const tint = 0.95 + hash1(p * 13 + 5) * 0.09;
    ctx.fillStyle = `rgba(255,${Math.round(240 * tint)},${Math.round(220 * tint)},0.35)`;
    ctx.fillRect(0, p * plank, s, plank);
    // cathedral figure: the hint of one, barely there. Tested at full
    // strength it reads as zebra striping on every small merged prop (the
    // arcs stack where they nest) — at this stylisation level flat grain
    // plus plank tone reads as wood, arcs do not.
    const cx = hash1(p * 3 + 1) * s;
    for (let a = 0; a < 5; a++) {
      ctx.strokeStyle = `rgba(48,29,17,0.032)`;
      ctx.lineWidth = 1.2 + a * 1.4;
      ctx.beginPath();
      ctx.ellipse(cx, p * plank + plank * 0.5, 12 + a * 15, 5 + a * 6, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    for (let k = 0; k < 15; k++) {
      const gy = p * plank + (0.04 + hash1(p * 31 + k * 3.1) * 0.92) * plank;
      ctx.strokeStyle = `rgba(44,26,15,${0.045 + hash1(k * 5 + p) * 0.07})`;
      ctx.lineWidth = 0.7 + hash1(k * 2.3 + p) * 1.4;
      ctx.beginPath();
      ctx.moveTo(0, gy);
      for (let x = 1; x <= 4; x++) ctx.lineTo((x / 4) * s, gy + Math.sin(x * 1.7 + k) * 3);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(46,29,17,0.30)'; // plank seam — a shade line, not a gap
    ctx.fillRect(0, (p + 1) * plank - 2, s, 3);
  }
  // a little sun-bleach near one edge, so a big surface is not one flat value
  const g = ctx.createLinearGradient(0, 0, s, 0);
  g.addColorStop(0, 'rgba(255,226,180,0.10)');
  g.addColorStop(0.5, 'rgba(255,226,180,0)');
  g.addColorStop(1, 'rgba(60,36,20,0.10)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
});
const woodRough = dataMap(256, (ctx, s) => {
  ctx.fillStyle = '#a8a8a8'; // ~0.66 base roughness
  ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 900; i++) {
    const v = Math.round(255 * (0.58 + hash1(i * 7.1) * 0.28));
    ctx.fillStyle = `rgba(${v},${v},${v},0.45)`;
    ctx.fillRect(hash1(i * 1.3) * s, hash1(i * 2.9) * s, 2 + hash1(i) * 6, 1);
  }
});
const woodNormal = normalMapFrom(256, WOOD_H, { strength: 0.14 });

/** Marble/quartz worktop: cool white body, grey veins, fine sparkle, and a
 *  roughness map so the polished field differs from the sanded edge. */
const MARBLE_H = (ctx, s) => {
  ctx.fillStyle = '#b4b4b4';
  ctx.fillRect(0, 0, s, s);
  for (let v = 0; v < 9; v++) {
    let x = hash1(v * 3 + 2) * s;
    let y = hash1(v * 7 + 4) * s;
    ctx.strokeStyle = `rgba(250,250,250,${0.5 + hash1(v) * 0.3})`;
    ctx.lineWidth = 1 + hash1(v * 3) * 2.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    for (let st = 0; st < 10; st++) {
      x += (hash1(v * 11 + st) - 0.4) * 40;
      y += (hash1(v * 13 + st * 2) - 0.5) * 30;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  for (let i = 0; i < 2500; i++) {
    const v = Math.round(255 * (0.55 + hash1(i * 3.7) * 0.4));
    ctx.fillStyle = `rgba(${v},${v},${v},0.35)`;
    ctx.fillRect(hash1(i) * s, hash1(i * 2.3) * s, 2, 2);
  }
};
const marbleMap = colourMap(256, (ctx, s) => {
  const g = ctx.createLinearGradient(0, 0, s, s);
  g.addColorStop(0, '#efeeea');
  g.addColorStop(1, '#e3e2dd');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  for (let v = 0; v < 9; v++) {
    let x = hash1(v * 3 + 2) * s;
    let y = hash1(v * 7 + 4) * s;
    ctx.strokeStyle = `rgba(139,146,152,${0.2 + hash1(v) * 0.22})`;
    ctx.lineWidth = 0.9 + hash1(v * 3) * 2.2;
    ctx.beginPath();
    ctx.moveTo(x, y);
    for (let st = 0; st < 10; st++) {
      x += (hash1(v * 11 + st) - 0.4) * 40;
      y += (hash1(v * 13 + st * 2) - 0.5) * 30;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.strokeStyle = `rgba(255,255,255,0.5)`;
    ctx.lineWidth = 0.7;
    ctx.stroke();
  }
  for (let i = 0; i < 900; i++) {
    // mica sparkle
    const v = Math.round(200 + hash1(i * 5.1) * 55);
    ctx.fillStyle = `rgba(${v},${v},${v},${0.2 + hash1(i) * 0.4})`;
    ctx.fillRect(hash1(i * 1.7) * s, hash1(i * 2.1) * s, 1.6, 1.6);
  }
});
const marbleRough = dataMap(256, (ctx, s) => {
  ctx.fillStyle = '#3a3a3a'; // polished: low roughness (a data map, NOT multiplied by colour)
  ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 500; i++) {
    const v = Math.round(255 * (0.16 + hash1(i * 9.3) * 0.2));
    ctx.fillStyle = `rgba(${v},${v},${v},0.5)`;
    ctx.fillRect(hash1(i * 2.2) * s, hash1(i * 4.4) * s, 3, 3);
  }
});
const marbleNormal = normalMapFrom(128, MARBLE_H, { strength: 0.5 });

/** Ceramic tile with real grout: bevelled edges, tonal variation per tile,
 *  a sheen streak, and grout that is matte and slightly gritty. */
function tileColour({ base = [247, 249, 247], grout = [178, 174, 166], n = 4 } = {}) {
  return colourMap(256, (ctx, s) => {
    ctx.fillStyle = `rgb(${grout[0]},${grout[1]},${grout[2]})`;
    ctx.fillRect(0, 0, s, s);
    const t = s / n;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        const g = 0.965 + hash1(i * 11 + j * 7) * 0.06;
        ctx.fillStyle = `rgb(${Math.round(base[0] * g)},${Math.round(base[1] * g)},${Math.round(base[2] * g)})`;
        ctx.fillRect(i * t + 2.5, j * t + 2.5, t - 5, t - 5);
        // bevel: light top-left, shade bottom-right
        ctx.fillStyle = 'rgba(255,255,255,0.32)';
        ctx.fillRect(i * t + 2.5, j * t + 2.5, t - 5, 2.5);
        ctx.fillRect(i * t + 2.5, j * t + 2.5, 2.5, t - 5);
        ctx.fillStyle = 'rgba(90,96,92,0.22)';
        ctx.fillRect(i * t + 2.5, j * t + t - 5, t - 5, 2.5);
        ctx.fillRect(i * t + t - 5, j * t + 2.5, 2.5, t - 5);
        // glaze streak
        ctx.fillStyle = `rgba(255,255,255,${0.05 + hash1(i * 5 + j * 3) * 0.07})`;
        ctx.fillRect(i * t + 6, j * t + 6, t - 14, (t - 12) * 0.3);
      }
    }
    for (let i = 0; i < 1400; i++) {
      // grout grit
      const v = Math.round(150 + hash1(i * 2.7) * 60);
      ctx.fillStyle = `rgba(${v},${v - 4},${v - 10},0.25)`;
      ctx.fillRect(hash1(i * 1.1) * s, hash1(i * 3.3) * s, 1.6, 1.6);
    }
  });
}
function tileHeight(n = 4) {
  return (ctx, s) => {
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(0, 0, s, s);
    const t = s / n;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        ctx.fillStyle = '#c8c8c8';
        ctx.fillRect(i * t + 3, j * t + 3, t - 6, t - 6);
        ctx.fillStyle = 'rgba(255,255,255,0.22)';
        ctx.fillRect(i * t + 3, j * t + 3, t - 6, 3);
      }
    }
  };
}
function tileRough(n = 4, groutRough = 0.92) {
  return dataMap(256, (ctx, s) => {
    const gv = Math.round(groutRough * 255);
    ctx.fillStyle = `rgb(${gv},${gv},${gv})`;
    ctx.fillRect(0, 0, s, s);
    const t = s / n;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        const v = Math.round((0.45 + hash1(i * 7 + j) * 0.12) * 255); // semi-gloss ceramic, not a mirror
        ctx.fillStyle = `rgb(${v},${v},${v})`;
        ctx.fillRect(i * t + 3, j * t + 3, t - 6, t - 6);
      }
    }
  });
}

/** Fabric: a real over-under weave with a slub (fat-thin thread) and fuzz. */
function fabricHeight({ thread = 4 } = {}) {
  return (ctx, s) => {
    ctx.fillStyle = '#7a7a7a';
    ctx.fillRect(0, 0, s, s);
    for (let y = 0; y < s; y += thread) {
      const over = (Math.floor(y / thread) % 2) * thread;
      for (let x = 0; x < s; x += thread * 2) {
        const bump = 0.75 + hash1(x * 0.7 + y * 1.3) * 0.45; // slub
        const v = Math.round(255 * clamp(bump, 0, 1));
        ctx.fillStyle = `rgb(${v},${v},${v})`;
        ctx.fillRect(x + over, y, thread, thread);
        ctx.fillStyle = 'rgba(40,40,40,0.5)';
        ctx.fillRect(x + over, y + thread - 1, thread, 1);
      }
    }
    for (let i = 0; i < 2600; i++) {
      const v = Math.round(255 * (0.35 + hash1(i * 5.1) * 0.6));
      ctx.fillStyle = `rgba(${v},${v},${v},0.25)`;
      ctx.fillRect(hash1(i * 1.7) * s, hash1(i * 2.9) * s, 1.5, 1.5);
    }
  };
}
/** A weave map multiplied by any colour: `weaveMap` is grey, so one canvas
 *  serves the couch, the bedding, the towels, the rug and the cushions. */
const weaveMap = colourMap(128, (ctx, s) => {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, s, s);
  const t = 4;
  for (let y = 0; y < s; y += t) {
    const over = (Math.floor(y / t) % 2) * t;
    for (let x = 0; x < s; x += t * 2) {
      const g = Math.round(225 * (0.86 + hash1(x * 0.7 + y * 1.3) * 0.24));
      ctx.fillStyle = `rgb(${g},${g},${g})`;
      ctx.fillRect(x + over, y, t, t);
    }
    ctx.fillStyle = 'rgba(70,70,80,0.10)';
    ctx.fillRect(0, y + t - 1, s, 1);
  }
  for (let i = 0; i < 900; i++) {
    const g = Math.round(210 + hash1(i * 3.3) * 45);
    ctx.fillStyle = `rgba(${g},${g},${g},0.5)`;
    ctx.fillRect(hash1(i * 1.1) * s, hash1(i * 2.7) * s, 2, 1);
  }
});
const weaveNormal = normalMapFrom(128, fabricHeight(), { strength: 0.12 });

const plasterMap = colourMap(256, (ctx, s) => {
  ctx.fillStyle = '#ffffff'; // the plaster token colour rides in on the material
  ctx.fillRect(0, 0, s, s);
  for (let b = 0; b < 46; b++) {
    const x = hash1(b * 3.7) * s;
    const y = hash1(b * 5.1) * s;
    const r = 18 + hash1(b) * 55;
    const warm = hash1(b * 2.3) > 0.5;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, warm ? 'rgba(255,250,238,0.055)' : 'rgba(150,146,136,0.055)');
    g.addColorStop(1, 'rgba(217,211,199,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  for (let i = 0; i < 1400; i++) {
    // float texture — kept faint: at 1.4 m per tile this reads on a lit wall,
    // and anything stronger shimmers when a camera skims the surface
    const a = 0.015 + hash1(i * 1.9) * 0.025;
    ctx.fillStyle = hash1(i) > 0.5 ? `rgba(255,255,255,${a})` : `rgba(120,116,108,${a})`;
    ctx.fillRect(hash1(i * 2.7) * s, hash1(i * 4.3) * s, 1.6, 1.6);
  }
});
/** Brushed metal: anisotropic streaks in both colour and roughness. */
const metalMap = colourMap(128, (ctx, s) => {
  ctx.fillStyle = '#cdd2d9';
  ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 900; i++) {
    const y = hash1(i * 2.3) * s;
    const v = Math.round(200 + hash1(i) * 55);
    ctx.strokeStyle = `rgba(${v},${v + 2},${v + 6},0.14)`;
    ctx.lineWidth = 0.6 + hash1(i * 3.1);
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(s, y + (hash1(i * 5.7) - 0.5) * 2);
    ctx.stroke();
  }
});
const metalRough = dataMap(128, (ctx, s) => {
  ctx.fillStyle = '#606060';
  ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 700; i++) {
    const y = hash1(i * 3.1) * s;
    const v = Math.round(255 * (0.2 + hash1(i) * 0.4));
    ctx.strokeStyle = `rgba(${v},${v},${v},0.35)`;
    ctx.lineWidth = 0.8 + hash1(i * 1.7);
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(s, y);
    ctx.stroke();
  }
});

/** Rug: a woven pile with bands, drawn warm-neutral so TOKENS.rug tints it. */
const rugMap = colourMap(256, (ctx, s) => {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, s, s);
  for (let y = 0; y < s; y += 6) {
    const band = 0.93 + hash1(Math.floor(y / 6) * 7.3) * 0.1;
    ctx.fillStyle = `rgba(${Math.round(255 * band)},${Math.round(250 * band)},${Math.round(240 * band)},0.85)`;
    ctx.fillRect(0, y, s, 5);
  }
  for (let i = 0; i < 2400; i++) {
    // pile tufts
    const v = Math.round(220 + hash1(i * 1.3) * 35);
    ctx.fillStyle = `rgba(${v},${v - 4},${v - 12},0.32)`;
    ctx.fillRect(hash1(i * 2.7) * s, hash1(i * 5.9) * s, 2, 3);
  }
  // a couple of woven stripes in a slightly deeper tone
  for (const off of [0.28, 0.66]) {
    ctx.fillStyle = 'rgba(120,104,84,0.14)';
    ctx.fillRect(0, s * off, s, 9);
    ctx.fillRect(0, s * off + 13, s, 4);
  }
});
const rugNormal = normalMapFrom(128, fabricHeight({ thread: 6 }), { strength: 0.16 });

/** Book spines: a shelf of them reads as books at 2 m, not as a brown block. */
const spineMap = colourMap(128, (ctx, s) => {
  ctx.fillStyle = '#2a2f38';
  ctx.fillRect(0, 0, s, s);
  const hues = ['#7a4234', '#3f5c6b', '#8a7340', '#4a5a3f', '#6b4a63', '#2f4550', '#9a6b3a'];
  let x = 0;
  let i = 0;
  while (x < s) {
    const w = 6 + hash1(i * 3.7) * 14;
    const h = hues[Math.floor(hash1(i * 9.1) * hues.length) % hues.length];
    ctx.fillStyle = h;
    ctx.fillRect(x, 0, w - 1.4, s);
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.fillRect(x + w - 2.6, 0, 1.6, s);
    ctx.fillStyle = `rgba(240,232,214,${0.5 + hash1(i) * 0.4})`;
    ctx.fillRect(x + 1.5, s * (0.2 + hash1(i * 2) * 0.3), Math.max(2, w - 5), 2); // title band
    ctx.fillRect(x + 1.5, s * 0.78, Math.max(2, w - 6), 1.5);
    i++;
    x += w;
  }
});

/** Wall art: two framed prints' worth of abstract shape language that matches
 *  the room's palette (mustard, coral, oak, sky) rather than stock art. */
const posterMap = colourMap(256, (ctx, s) => {
  ctx.fillStyle = '#efe9dd';
  ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = '#c9dcea';
  ctx.beginPath();
  ctx.arc(s * 0.36, s * 0.42, s * 0.24, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#e8b04a';
  ctx.fillRect(s * 0.5, s * 0.24, s * 0.3, s * 0.44);
  ctx.fillStyle = '#2b2f38';
  ctx.beginPath();
  ctx.moveTo(s * 0.16, s * 0.82);
  ctx.lineTo(s * 0.52, s * 0.6);
  ctx.lineTo(s * 0.86, s * 0.82);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#ff8f7d';
  ctx.beginPath();
  ctx.arc(s * 0.7, s * 0.78, s * 0.06, 0, Math.PI * 2);
  ctx.fill();
  for (let i = 0; i < 1500; i++) {
    // paper tooth
    ctx.fillStyle = `rgba(120,110,95,${hash1(i * 2.7) * 0.06})`;
    ctx.fillRect(hash1(i * 1.3) * s, hash1(i * 3.1) * s, 1.5, 1.5);
  }
});

/** A leaf with a midrib and a paler margin: drawn on a card the leaf geometry
 *  uses, so a plant reads as foliage rather than green blobs. */
const leafMap = colourMap(128, (ctx, s) => {
  const g = ctx.createLinearGradient(0, 0, 0, s);
  g.addColorStop(0, '#f2f7e4');
  g.addColorStop(0.55, '#dbe8c6');
  g.addColorStop(1, '#c3d8a8');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  ctx.strokeStyle = 'rgba(255,255,255,0.72)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(s / 2, s);
  ctx.lineTo(s / 2, 0);
  ctx.stroke();
  ctx.lineWidth = 1.4;
  ctx.strokeStyle = 'rgba(255,255,255,0.38)';
  for (let i = 1; i < 9; i++) {
    const y = (i / 9) * s;
    ctx.beginPath();
    ctx.moveTo(s / 2, y);
    ctx.lineTo(s * 0.06, y - s * 0.12);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(s / 2, y);
    ctx.lineTo(s * 0.94, y - s * 0.12);
    ctx.stroke();
  }
  for (let i = 0; i < 900; i++) {
    ctx.fillStyle = `rgba(30,50,30,${hash1(i * 2.1) * 0.12})`;
    ctx.fillRect(hash1(i) * s, hash1(i * 3.7) * s, 2, 2);
  }
});

/** A terracotta pot with a thrown rim band and a mineral bloom. */
const potMap = colourMap(128, (ctx, s) => {
  const g = ctx.createLinearGradient(0, 0, 0, s);
  g.addColorStop(0, '#c2734c');
  g.addColorStop(1, '#9a5738');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  for (let y = 0; y < s; y += 7) {
    ctx.fillStyle = `rgba(255,255,255,${0.03 + hash1(y) * 0.05})`;
    ctx.fillRect(0, y, s, 3); // throwing rings
  }
  for (let i = 0; i < 500; i++) {
    ctx.fillStyle = `rgba(236,238,226,${hash1(i * 3.3) * 0.14})`;
    ctx.beginPath();
    ctx.arc(hash1(i) * s, hash1(i * 2.7) * s, 1 + hash1(i * 1.1) * 3, 0, Math.PI * 2);
    ctx.fill();
  }
});

/** The TV, ON: a soft bright still frame (the glow is the point — a black
 *  screen read as "off" in Step 8 and Brandon asked for a TV that glows). */
const tvScreenMap = colourMap(256, (ctx, s) => {
  const g = ctx.createLinearGradient(0, 0, s, s);
  g.addColorStop(0, '#1d3557');
  g.addColorStop(0.45, '#2f6f8f');
  g.addColorStop(0.72, '#8ec5d6');
  g.addColorStop(1, '#e7d3ae');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  // a horizon, a sun, a silhouette: enough to read as a paused nature shot
  ctx.fillStyle = 'rgba(255,226,170,0.62)';
  ctx.beginPath();
  ctx.arc(s * 0.68, s * 0.62, s * 0.09, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(16,26,36,0.85)';
  ctx.beginPath();
  ctx.moveTo(0, s * 0.78);
  ctx.lineTo(s * 0.3, s * 0.62);
  ctx.lineTo(s * 0.56, s * 0.8);
  ctx.lineTo(s * 0.82, s * 0.68);
  ctx.lineTo(s, s * 0.82);
  ctx.lineTo(s, s);
  ctx.lineTo(0, s);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  for (let y = 0; y < s; y += 3) ctx.fillRect(0, y, s, 1); // panel scanlines
});

/** A soft radial pool of shade: the contact shadow under every prop. */
const contactMap = makeTexture(
  paintCanvas(128, (ctx, s) => {
    const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.45, 'rgba(255,255,255,0.62)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
  }),
  { srgb: false },
);

// ---------------------------------------------------------------------------
// 4. Materials built from the surfaces above
// ---------------------------------------------------------------------------
/** `uvTile` (metres per texture tile) rides on the material so the merge
 *  helper in game/full-apartment.js can bake matching world UVs per part. */
function surface(color, opts = {}) {
  const { uvTile = 0.6, roughness = 0.8, metalness = 0, ...rest } = opts;
  // three.js multiplies roughnessMap.g by material.roughness. The roughness
  // canvases here are drawn in ABSOLUTE values (a porcelain rim ~0.2, matte
  // grout ~0.9), so when one is attached the multiplier must come to rest at
  // 1 — otherwise a 0.34 base × a 0.23 map is a mirror, and with no envmap a
  // mirror renders as black splotches. The `roughness` option then only
  // documents the intended average.
  const m = new THREE.MeshStandardMaterial({
    color: new THREE.Color(color),
    roughness: rest.roughnessMap ? 1 : roughness,
    metalness,
    ...rest,
  });
  m.userData.uvTile = uvTile;
  return m;
}

const SURFACES = {
  /** furniture wood: grain + relief + wear, one tile per 60 cm */
  wood: () => surface(TOKENS.walnut, { uvTile: 0.95, roughness: 0.62, map: woodMap, normalMap: woodNormal, roughnessMap: woodRough, normalScale: new THREE.Vector2(0.35, 0.35) }),
  /** lighter, warmer wood for shelves/frames where walnut goes muddy */
  woodPale: () => surface(0xb08a5c, { uvTile: 0.9, roughness: 0.66, map: woodMap, normalMap: woodNormal, roughnessMap: woodRough, normalScale: new THREE.Vector2(0.3, 0.3) }),
  marble: () => surface(TOKENS.uiPaper, { uvTile: 0.8, roughness: 0.34 }),
  bathTile: () => surface(0xdfe6e2, { uvTile: 0.25, roughness: 0.5, map: tileColour({ n: 4 }), normalMap: normalMapFrom(128, tileHeight(4), { strength: 0.2 }), roughnessMap: tileRough(4), normalScale: new THREE.Vector2(0.5, 0.5) }),
  kitchenTile: () => surface(0xe9e6dd, { uvTile: 0.2, roughness: 0.5, map: tileColour({ n: 8, base: [238, 236, 228], grout: [176, 172, 162] }), normalMap: normalMapFrom(128, tileHeight(8), { strength: 0.18 }), roughnessMap: tileRough(8), normalScale: new THREE.Vector2(0.45, 0.45) }),
  // Plaster carries its float texture in the COLOUR map only. A normal map
  // here speckled every shadow-casting wall slab with acne in testing — even
  // at normalScale 0.16 with shadowSide: BackSide — because the sun rakes
  // these boxes at a brutal angle and the wall meshes must keep castShadow
  // (they carve the window patch of sunlight on the floor). The mottled
  // float map gives the walls their life instead; it cannot shimmer.
  plaster: () => surface(TOKENS.plaster, { uvTile: 1.4, roughness: 0.95, map: plasterMap }),
  // TOKENS.metal (0x23262b) at metalness .6 renders pure black with no
  // envmap in the scene — Step 8's taps read as holes. Lifted toward a
  // mid steel and made less metallic so the diffuse term survives; the
  // brushed streaks come from the map.
  metal: () => surface(0x79838e, { uvTile: 0.3, roughness: 0.42, metalness: 0.35, map: metalMap, roughnessMap: metalRough }),
  rug: () => surface(TOKENS.rug, { uvTile: 0.5, roughness: 0.95, map: rugMap }),
  spines: () => surface(0xffffff, { uvTile: 0.34, roughness: 0.78, map: spineMap }),
  poster: () => surface(0xffffff, { uvTile: 0.55, roughness: 0.9, map: posterMap }),
  pot: () => surface(0xffffff, { uvTile: 0.3, roughness: 0.82, map: potMap }),
  leaf: () => surface(TOKENS.leaf, { uvTile: 0.16, roughness: 0.62, map: leafMap, side: THREE.DoubleSide }),
};

/** The fabric family: one weave canvas, tinted per use (couch, bedding,
 *  cushions, towels, the throw). Same look the style test set, now with relief. */
function fabric(color, { uvTile = 0.12, roughness = 0.92, sheen = 0.25 } = {}) {
  // Colour-only weave. Tested adding weaveNormal at four strengths: in THIS
  // scene (soft interior fills, raking sun through one window) any tangent
  // relief on the flat cloth boxes ate 60-90% of the diffuse term on the
  // mats and bedding — the measured probe is on record in git. The weave
  // canvas alone already reads as cloth at gameplay distance; relief can come
  // back only as part of a lighting rework (a real envmap).
  const m = surface(color, {
    uvTile,
    roughness,
    map: weaveMap,
  });
  m.sheen = sheen;
  m.sheenRoughness = 0.7;
  m.sheenColor = new THREE.Color(0xffffff).multiplyScalar(0.35);
  return m;
}

/** The TV screen: emissive, so the panel is the brightest thing in the corner
 *  of the room even though it is not a real light (the light cap is 6). */
function tvScreenMaterial() {
  return new THREE.MeshStandardMaterial({
    color: new THREE.Color(0x0c1017),
    emissive: new THREE.Color(0xffffff),
    emissiveMap: tvScreenMap,
    emissiveIntensity: 1.12,
    roughness: 0.28,
    metalness: 0,
  });
}

/** The soft additive halo in front of the screen + the pool of light it
 *  throws on the wall around it. Not a light: a decal. */
function glowMaterial(tint = 0x9ecbe8, opacity = 0.35) {
  return new THREE.MeshBasicMaterial({
    color: new THREE.Color(tint),
    map: contactMap,
    transparent: true,
    opacity,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
}

// ---------------------------------------------------------------------------
// 5. Contact shadows — one InstancedMesh for every prop in the flat
// ---------------------------------------------------------------------------
/**
 * Place soft shade pools where things meet the floor. One instanced mesh, one
 * draw call, `depthWrite:false` and a polygon offset so it sits on the oak
 * without fighting the real shadow map. `spots` = [{ x, z, w, d, k }] where k
 * scales the opacity of that pool (a bed sits darker than a chair).
 */
function contactShadows(parent, spots, { y = 0.004, color = 0x1a1712, opacity = 0.5, name = 'contact-shadows' } = {}) {
  if (!spots.length) return null;
  const geo = new THREE.PlaneGeometry(1, 1);
  geo.rotateX(-Math.PI / 2);
  const mat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(color),
    map: contactMap,
    transparent: true,
    opacity,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: -2,
    polygonOffsetUnits: -2,
    toneMapped: false,
  });
  const mesh = new THREE.InstancedMesh(geo, mat, spots.length);
  mesh.name = name;
  mesh.frustumCulled = false; // a floor pool is never the thing that pops in late
  const o = new THREE.Object3D();
  spots.forEach((sp, i) => {
    o.position.set(sp.x, y + (sp.y ?? 0), sp.z);
    o.scale.set(sp.w, 1, sp.d);
    o.rotation.set(0, sp.rot ?? 0, 0);
    o.updateMatrix();
    mesh.setMatrixAt(i, o.matrix);
  });
  mesh.instanceMatrix.needsUpdate = true;
  mesh.renderOrder = 2;
  parent.add(mesh);
  return mesh;
}

// ---------------------------------------------------------------------------
// 6. Leaves, so plants are plants
// ---------------------------------------------------------------------------
/**
 * A blade/leaf as a strip of quads that curves outward from the midrib (a
 * real leaf is a shallow trough, not a plane) and droops toward its tip.
 * `len`/`wid` in metres; `bend` is how much the tip falls; `twist` curls it.
 */
function leafGeo({ len = 0.34, wid = 0.07, bend = 0.12, twist = 0.35, segs = 5, cup = 0.35 } = {}) {
  const pos = [];
  const nor = [];
  const uv = [];
  const idx = [];
  const P = (u) => [0, -bend * u * u, len * u]; // droop profile in local Y/Z
  for (let i = 0; i <= segs; i++) {
    const u = i / segs;
    const halfW = wid * 0.5 * Math.sin(Math.PI * Math.min(0.98, 0.22 + u * 0.86)); // leaf profile: narrow base, wide middle, pointed tip
    const c = P(u);
    const curl = twist * u * u;
    for (const side of [-1, 1]) {
      const x = side * halfW;
      const z = c[2];
      const y = c[1] + cup * (halfW * halfW) * 4 - cup * halfW * 0.5; // trough across the midrib
      pos.push(x, y, z);
      nor.push(-side * 0.35, 1, curl * 0.5);
      uv.push(side < 0 ? 0 : 1, u);
    }
  }
  for (let i = 0; i < segs; i++) {
    const a = i * 2;
    idx.push(a, a + 1, a + 3, a, a + 3, a + 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

/** A rounded shrub leaf: the same strip closed into a paddle. */
function broadLeafGeo({ len = 0.2, wid = 0.16, bend = 0.06, segs = 4 } = {}) {
  return leafGeo({ len, wid, bend, twist: 0.15, segs: segs + 1, cup: 0.7 });
}

export {
  colourMap,
  dataMap,
  normalMapFrom,
  worldUV,
  surface,
  fabric,
  SURFACES,
  tvScreenMaterial,
  glowMaterial,
  contactShadows,
  leafGeo,
  broadLeafGeo,
  contactMap,
  tvScreenMap,
};
